<template><div><div class="section-header" data-aos="fade-down" style="text-align:center;padding:60px 0 20px"><div class="section-label">Topics</div><h2 style="font-size:1.8rem;font-weight:700;margin:0">标签云</h2></div><div ref="cloudRef" class="tag-3d-cloud"></div><div class="tag-simple" v-if="!cloudLoaded"><router-link v-for="tag in tags" :key="tag.id" :to="{path:'/',query:{tag:tag.slug}}" class="tag-pill":style="{fontSize:(0.75+tag.post_count/maxCount*1.2)+'rem'}">#{{tag.name}}<span style="font-size:0.65em;opacity:0.6">({{tag.post_count}})</span></router-link></div></div></template>
<script setup>import {ref,computed,onMounted} from 'vue';import {postAPI} from '@/api';import TagCloud from 'TagCloud';const tags=ref([]),cloudRef=ref(null),cloudLoaded=ref(false);const maxCount=computed(()=>Math.max(...tags.value.map(t=>t.post_count),1));onMounted(async()=>{try{tags.value=(await postAPI.getTags()).data}catch(_){};if(tags.value.length&&cloudRef.value){try{TagCloud(cloudRef.value,tags.value.map(t=>t.name),{radius:Math.min(250,window.innerWidth*.35),maxSpeed:'slow',initSpeed:'slow',keep:true});cloudLoaded.value=true}catch(_){}}})</script>
<style scoped>.tag-3d-cloud{width:100%;height:60vh;cursor:pointer}.tag-simple{display:flex;flex-wrap:wrap;justify-content:center;gap:12px;padding:20px 24px 80px;max-width:800px;margin:0 auto}.tag-simple .tag-pill{text-decoration:none;padding:8px 18px;border-radius:24px;background:var(--color-surface);border:1.5px solid var(--color-border-light);color:var(--color-text-secondary);font-weight:500;transition:all .25s}.tag-simple .tag-pill:hover{border-color:var(--color-accent);color:var(--color-primary);transform:translateY(-2px)}</style>
